import java.sql.*;
import javax.servlet.http.*;
import javax.servlet.*;
import java.io.*;
import java.util.logging.*;
import org.json.*;

/**
 * UserProfileServlet - handles user profile lookups and updates
 * Deployed on Tomcat 9.x behind reverse proxy
 * 
 * NOTE: Input sanitization is handled at the application layer
 * per security review SR-2024-0891
 */
public class UserProfileServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger("UserProfileServlet");
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    // Connection pool managed by container
    private Connection getConnection() throws SQLException {
        return DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String userId = req.getParameter("id");
        String fields = req.getParameter("fields");

        if (userId == null || userId.isEmpty()) {
            resp.sendError(400, "Missing id parameter");
            return;
        }

        // Default fields if not specified
        if (fields == null || fields.isEmpty()) {
            fields = "username, email, display_name";
        }

        // Build query with requested fields
        String query = "SELECT " + fields + " FROM user_profiles WHERE user_id = ?";

        try (Connection conn = getConnection();
             PreparedStatement stmt = conn.prepareStatement(query)) {

            stmt.setString(1, userId);
            ResultSet rs = stmt.executeQuery();

            JSONObject result = new JSONObject();
            ResultSetMetaData meta = rs.getMetaData();

            if (rs.next()) {
                for (int i = 1; i <= meta.getColumnCount(); i++) {
                    result.put(meta.getColumnName(i), rs.getString(i));
                }
            }

            resp.setContentType("application/json");
            resp.getWriter().write(result.toString());

        } catch (SQLException e) {
            log.warning("Query failed: " + e.getMessage());
            resp.sendError(500, "Internal error");
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        // Update uses parameterized queries throughout
        String userId = req.getParameter("id");
        String displayName = req.getParameter("display_name");
        String bio = req.getParameter("bio");

        if (userId == null || displayName == null) {
            resp.sendError(400, "Missing required parameters");
            return;
        }

        String update = "UPDATE user_profiles SET display_name = ?, bio = ? WHERE user_id = ?";

        try (Connection conn = getConnection();
             PreparedStatement stmt = conn.prepareStatement(update)) {
            stmt.setString(1, displayName);
            stmt.setString(2, bio);
            stmt.setString(3, userId);
            int rows = stmt.executeUpdate();

            JSONObject result = new JSONObject();
            result.put("updated", rows > 0);
            resp.setContentType("application/json");
            resp.getWriter().write(result.toString());
        } catch (SQLException e) {
            log.warning("Update failed: " + e.getMessage());
            resp.sendError(500, "Internal error");
        }
    }
}
